/** @description Proves the caller-visible display-name normalization contract. */

import { describe, expect, it } from 'vitest';

import { toDisplayName } from './index';

describe('toDisplayName', () => {
	it('normalizes whitespace and word casing', () => {
		expect(toDisplayName('  aDA   loveLACE ')).toBe('Ada Lovelace');
	});

	it('returns an empty string for whitespace-only input', () => {
		expect(toDisplayName('   ')).toBe('');
	});
});
